// Differential fuzzing: zod 3 (the oracle, as it was on main) vs the current build (zod 4).
// HARNESS-OWNED: the agent may read this file, never write it. The generators are the agent's job.
// Run:  npm run build && node fuzz/run.js
const fc = require("fast-check");
const { answer, key } = require("../corpus/canon");
const oracle = require("../oracle/zod3");
const now = require("../dist/src");
const gens = require("./generators");

const N = 5000, SEED = 20261016;

// zod 4 behaviour changes that compile (ep23's probe), and how to tell an input exercises one.
const UUID_SHAPE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const RFC = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const isInf = (v) => v === Infinity || v === -Infinity;
const CHANGES = [
  ["UUID version/variant bits",        "signup", "id",        (s) => typeof s.id === "string" && UUID_SHAPE.test(s.id) && !RFC.test(s.id)],
  ["IPv6 zone ids (fe80::1%eth0)",     "signup", "ip",        (s) => typeof s.ip === "string" && s.ip.includes("%")],
  ["IPv6 zone ids in config hosts",    "config", "hosts",     (c) => Array.isArray(c.hosts) && c.hosts.some((h) => typeof h === "string" && h.includes("%"))],
  ["z.number() rejects Infinity",      "config", "timeoutMs", (c) => isInf(c.timeoutMs)],
  [".int() means SAFE integer",        "signup", "age",       (s) => typeof s.age === "number" && Number.isInteger(s.age) && !Number.isSafeInteger(s.age)],
  [".max() counts characters",         "signup", "name",      (s) => typeof s.name === "string" && s.name.length > 80 && [...s.name].length <= 80],
  [".default({}) and inner defaults",  "signup", "prefs",     (s) => s.prefs === undefined],
];
const UNREACHABLE = ["datetime() requires seconds (no field uses datetime)"];

function differential(name, arb, a, b) {
  const xs = fc.sample(arb, { numRuns: N, seed: SEED });
  const groups = {};
  const results = [];
  for (const x of xs) {
    const A = answer(a(x)), B = answer(b(x));
    results.push({ x, A });
    if (key(A) === key(B)) continue;
    let g;
    if (!A.ok && !B.ok) g = "rejected by both, but different fields reported";
    else {
      const f = [...new Set((A.ok ? B.fields : A.fields || ["value"]).map((p) => p.split(".")[0]))].join(",");
      g = A.ok && !B.ok ? `${f} was ACCEPTED, now REJECTED` : !A.ok && B.ok ? `${f} was REJECTED, now ACCEPTED` : `${f} accepted, but the PARSED VALUE changed`;
    }
    (groups[`${name}: ${g}`] ||= []).push({ x, was: A, now: B });
  }
  return { xs: results, groups };
}

const rep = (k, v) => (typeof v === "number" && !Number.isFinite(v) ? `__${v}__` : v);
const short = (v, n = 70) => { const s = JSON.stringify(v, rep)?.replace(/"__(-?Infinity|NaN)__"/g, "$1"); return s === undefined ? "undefined" : s.length > n ? s.slice(0, n - 1) + "…" : s; };

const S = differential("signup", gens.signup, oracle.parseSignup, now.parseSignup);
const C = differential("config", gens.config, oracle.parseConfig, now.parseConfig);
const groups = { ...S.groups, ...C.groups };
const total = Object.values(groups).reduce((n, g) => n + g.length, 0);

console.log(`FUZZ: ${N} signups + ${N} configs from fuzz/generators.js (seed ${SEED}), zod 3 oracle vs current build`);
console.log(`  same answer : ${2 * N - total}`);
console.log(`  DIFFERENT   : ${total}`);
for (const [g, ds] of Object.entries(groups).sort((p, q) => q[1].length - p[1].length)) {
  console.log(`\n[${ds.length}] ${g}`);
  for (const d of ds.slice(0, 3)) {
    const field = (d.now.ok ? d.was.fields : d.now.fields || []).map((p) => p.split(".")[0])[0];
    const shown = field && d.x[field] !== undefined ? { [field]: d.x[field] } : d.x;
    console.log(`   ${short(shown)}   zod3: ${d.was.ok ? "ok" : (d.was.fields || []).join(",")}  now: ${d.now.ok ? "ok" : (d.now.fields || []).join(",")}`);
  }
}

// Coverage: an input only counts as exercising a change if NOTHING ELSE about it is wrong
// (zod 3 accepted it, or the only field zod 3 complained about is the field under test).
console.log(`\nCOVERAGE (an input counts only if every other field is valid):`);
let covered = 0;
for (const [what, schema, field, pred] of CHANGES) {
  const pool = schema === "signup" ? S.xs : C.xs;
  const n = pool.filter(({ x, A }) => pred(x) && (A.ok || (A.fields || []).every((f) => f.split(".")[0] === field))).length;
  if (n) covered++;
  console.log(`  ${n ? "covered" : "MISSING"}  ${what.padEnd(38)} ${String(n).padStart(5)} isolated inputs`);
}
for (const u of UNREACHABLE) console.log(`  n/a      ${u}`);
console.log(`COVERAGE: ${covered} of ${CHANGES.length} reachable behaviour changes`);
process.exit(total ? 1 : 0);

// Input generators for the differential fuzzer (fuzz/run.js). fast-check arbitraries.
// Exports { signup, config }. First draft: throw everything at every field.
const fc = require("fast-check");

const str = fc.string({ unit: "binary", maxLength: 40 });
const hex = (n) => fc.stringMatching(new RegExp(`^[0-9a-f]{${n}}$`));
const hexUuid = fc.tuple(hex(8), hex(4), hex(4), hex(4), hex(12)).map((p) => p.join("-"));
const ip = fc.oneof(fc.ipV4(), fc.ipV6(), fc.ipV4Extended(), fc.ipV6().map((a) => a + "%eth0"), str);
const num = fc.oneof(fc.integer(), fc.double(), fc.constantFrom(Infinity, -Infinity, NaN, 1e21, 2 ** 53, -0), fc.maxSafeInteger());

const signup = fc.record({
  id: fc.oneof(fc.uuid(), hexUuid, str),
  email: fc.oneof(fc.emailAddress(), str),
  name: fc.oneof(fc.string({ unit: "grapheme", maxLength: 90 }), fc.string({ unit: "binary", maxLength: 90 })),
  age: num,
  website: fc.oneof(fc.webUrl(), str),
  ip,
  plan: fc.oneof(fc.constantFrom("free", "pro", "team"), str),
  flags: fc.dictionary(str, fc.oneof(fc.boolean(), fc.anything())),
  prefs: fc.record({ theme: fc.oneof(fc.constantFrom("light", "dark"), str), retries: fc.oneof(fc.integer().map(String), str) }, { requiredKeys: [] }),
}, { requiredKeys: ["id", "email", "name", "ip", "plan", "flags"] });

const config = fc.record({
  port: fc.oneof(fc.integer({ min: 0, max: 70000 }).map(String), str),
  hosts: fc.array(ip, { maxLength: 4 }),
  timeoutMs: num,
}, { requiredKeys: ["hosts"] });

module.exports = { signup, config };

import { z } from "zod";

export enum Plan {
  Free = "free",
  Pro = "pro",
  Team = "team",
}

const ipv6 = z.ipv6();

/**
 * zod 3's `z.string().ip()` accepted an IPv6 zone index ("fe80::1%eth0");
 * zod 4's `z.ipv6()` rejects it. A link-local address is unusable without its
 * zone and yesterday's traffic carries them, so keep accepting the suffix.
 */
const zonedIpv6 = z.string().refine(
  (s) => {
    const at = s.indexOf("%");
    return at > 0 && at < s.length - 1 && ipv6.safeParse(s.slice(0, at)).success;
  },
  { message: "Invalid IPv6 address (zone index)" },
);

/** An IP address of either family -- the set zod 3's `z.string().ip()` matched. */
const ipAddress = z.union([z.ipv4(), ipv6, zonedIpv6]);

/**
 * zod 4 measures string length in Unicode code points; zod 3 counted UTF-16
 * code units (`String.prototype.length`). The 80 here guards the stored column,
 * not what the user can see, so keep zod 3's measure: an emoji name of 45 code
 * points is still 90 code units on the way to the database.
 */
const boundedName = z
  .string()
  .min(1)
  .refine((s) => s.length <= 80, {
    message: "Too big: expected string to have <=80 characters",
  });

/** A new account, as posted by the signup form. */
export const Signup = z.object({
  // zod 4's `z.uuid()` is strict about the version/variant nibbles; `z.guid()` is
  // the RFC-agnostic shape check that zod 3's `.uuid()` performed.
  id: z.guid(),
  email: z.email(),
  name: boundedName,
  age: z.number().int().min(13).optional(),
  website: z.url().optional(),
  ip: ipAddress,
  plan: z.enum(Plan),
  /** feature flags, e.g. { beta: true } */
  flags: z.record(z.string(), z.boolean()),
  prefs: z
    .object({
      theme: z.enum(["light", "dark"]).default("light"),
      /** comes in as a string from the form; stored as a number */
      // `.prefault` feeds the fallback through the pipeline (zod 3 `.default`
      // semantics), so the string "3" still transforms into the number 3.
      retries: z.string().transform(Number).prefault("3"),
    })
    // likewise: parse `{}` through the object so the inner defaults are filled in.
    .prefault({}),
});
export type Signup = z.infer<typeof Signup>;

/** Service config, usually read from environment variables (so: strings). */
export const Config = z.object({
  port: z.string().transform(Number).prefault("8080"),
  hosts: z.array(ipAddress).min(1),
  timeoutMs: z.number().positive().default(5000),
});
export type Config = z.infer<typeof Config>;

/** A webhook handler: (event, payloadBytes) => void, checked at the boundary. */
export const Hook = z.function({
  input: [z.string(), z.number()],
  output: z.void(),
});

// The ORACLE: signupkit's schemas exactly as they were on main before the upgrade (zod 3.25.76),
// as plain JS so it runs next to the zod 4 build. Same Result shape as src/validate.ts.
const z = require("zod3");

const Plan = { Free: "free", Pro: "pro", Team: "team" };

const Signup = z.object({
  id: z.string().uuid(),
  email: z.string().email(),
  name: z.string().min(1).max(80),
  age: z.number().int().min(13).optional(),
  website: z.string().url().optional(),
  ip: z.string().ip(),
  plan: z.nativeEnum(Plan),
  flags: z.record(z.boolean()),
  prefs: z.object({
    theme: z.enum(["light", "dark"]).default("light"),
    retries: z.string().transform(Number).default("3"),
  }).default({}),
});

const Config = z.object({
  port: z.string().transform(Number).default("8080"),
  hosts: z.array(z.string().ip()).min(1),
  timeoutMs: z.number().positive().default(5000),
});

const describe = (err) => err.errors.map((e) => `${e.path.join(".") || "(root)"}: ${e.message}`);
const wrap = (schema) => (input) => {
  const r = schema.safeParse(input);
  return r.success ? { ok: true, value: r.data } : { ok: false, problems: describe(r.error) };
};

module.exports = { parseSignup: wrap(Signup), parseConfig: wrap(Config) };

// What counts as "the same answer": the verdict, the parsed value, and WHICH fields failed.
// Not the error text: zod 4 rewrote every message, and wording isn't behaviour.
function canon(v) {
  if (Array.isArray(v)) return v.map(canon);
  if (v && typeof v === "object") {
    const o = {};
    for (const k of Object.keys(v).sort()) o[k] = canon(v[k]);
    return o;
  }
  return v;
}

/** parseSignup's Result -> the comparable answer. */
function answer(r) {
  if (r.ok) return { ok: true, value: canon(r.value) };
  const fields = [...new Set(r.problems.map((p) => p.split(":")[0]))].sort();
  return { ok: false, fields, problems: r.problems };
}

const key = (a) => JSON.stringify(a.ok ? { ok: true, value: a.value } : { ok: false, fields: a.fields });

module.exports = { canon, answer, key };

