// Input generators for the differential fuzzer (fuzz/run.js). fast-check arbitraries.
// Exports { signup, config }.
//
// Why this is not "throw everything at every field" (the first draft):
// fuzz/run.js only counts an input as exercising a behaviour change when every
// OTHER field is valid. A payload where four fields are garbage proves nothing
// about any single one of them -- it just lands in the useless
// "rejected by both, but different fields reported" bucket, which is what the
// first draft produced 3483 of while covering 2 of 7 changes.
//
// So: build a signup / config that zod 3 ACCEPTED, then mutate exactly ONE
// field. The per-field pools aim straight at zod 4's documented changes
// (uuid version/variant bits, IPv6 zone ids, Infinity, unsafe integers,
// code points vs UTF-16 code units, missing object defaults) and at the
// ordinary edges around each of them, so a difference is always attributable.

const fc = require("fast-check");

const DROP = Symbol("drop"); // mutation sentinel: delete the key entirely
const hex = (n) => fc.stringMatching(new RegExp(`^[0-9a-f]{${n}}$`));
const pick = (...vs) => fc.constantFrom(...vs);
const weighted = (...pairs) => fc.oneof(...pairs.map(([weight, arbitrary]) => ({ weight, arbitrary })));
const join = (xs) => xs.join("");

/* ----------------------------------------------------------------- id ---
 * zod 3 `.uuid()` vs zod 4 `z.guid()`/`z.uuid()`: the interesting axis is the
 * version nibble (3rd group, 1st char) and the variant nibble (4th group,
 * 1st char), so generate the shape with those two under explicit control. */
const uuidWith = (ver, vari) =>
  fc
    .tuple(hex(8), hex(4), ver, hex(3), vari, hex(3), hex(12))
    .map(([a, b, v, c, u, d, e]) => `${a}-${b}-${v}${c}-${u}${d}-${e}`);
const RFC_VER = pick("1", "2", "3", "4", "5", "6", "7", "8");
const RFC_VAR = pick("8", "9", "a", "b");
const ODD_VER = pick("0", "9", "a", "b", "c", "d", "e", "f");
const ODD_VAR = pick("0", "1", "2", "3", "4", "5", "6", "7", "c", "d", "e", "f");
const rfcUuid = uuidWith(RFC_VER, RFC_VAR);

const idOdd = weighted(
  [4, uuidWith(ODD_VER, RFC_VAR)], // right shape, non-RFC version
  [4, uuidWith(RFC_VER, ODD_VAR)], // right shape, non-RFC variant
  [2, uuidWith(ODD_VER, ODD_VAR)], // both bits off (e.g. a random 32-hex id)
  [1, pick(
    "00000000-0000-0000-0000-000000000000", // the nil uuid
    "ffffffff-ffff-ffff-ffff-ffffffffffff", // the max uuid
    "6BA7B810-9DAD-F1D1-80B4-00C04FD430C8", // uppercase + bad version
  )],
  [1, rfcUuid.map((s) => s.toUpperCase())],
  [1, rfcUuid.map((s) => `${s}\n`)],
  [1, rfcUuid.map((s) => s.replace(/-/g, ""))],
  [1, pick(
    "",
    "not-a-uuid",
    "{6ba7b810-9dad-11d1-80b4-00c04fd430c8}",
    "urn:uuid:6ba7b810-9dad-11d1-80b4-00c04fd430c8",
    "6ba7b810-9dad-11d1-80b4-00c04fd430c",
  )],
  [1, fc.string({ maxLength: 12 })],
);

/* -------------------------------------------------------------- email --- */
const emailOk = fc.stringMatching(/^[a-z0-9]{2,8}@[a-z0-9]{2,8}\.(com|org|net)$/);
const emailOdd = weighted(
  [3, pick(
    "a@b", "a@b.c", "user@localhost", "a+tag@x.com", "a.b@x.co.uk", "A@B.COM",
    "user name@x.com", "userä@x.com", "üser@x.com", "a@exämple.com",
    "a@xn--80ak6aa92e.com", "a@b..com", "a@-b.com", "a@b-.com", ".a@b.com", "a.@b.com",
    "a@[127.0.0.1]", "a@1.2.3.4", '"a b"@x.com', "a@b.com.", "a@b.com ", " a@b.com",
    "a@b.com\n", "a@@b.com", "@b.com", "a@", "",
  )],
  [1, fc.emailAddress()],
  [1, fc.string({ maxLength: 12 })],
);

/* --------------------------------------------------------------- name ---
 * The change: zod 4 `.max(80)` counts code points, zod 3 counted UTF-16 code
 * units. Astral characters are 2 units / 1 point each, so 41-60 of them is
 * >80 units but <=80 points -- exactly the window the two measures disagree. */
const ASTRAL = pick("\u{1F600}", "\u{1F44D}", "\u{1F389}", "\u{1D11E}", "\u{1F9D1}", "\u{1F680}");
const astralRun = (min, max) => fc.array(ASTRAL, { minLength: min, maxLength: max }).map(join);
const nameOdd = weighted(
  [5, astralRun(41, 60)], // >80 code units, <=80 code points
  [2, astralRun(1, 40)], // within 80 either way: must stay accepted
  [2, pick(
    "a".repeat(80), "a".repeat(81), "a".repeat(200), "", " ", "\n",
    "\u{1F1FA}\u{1F1F8}".repeat(25), // 25 flags: 100 units, 50 points
    "\u{1F468}‍\u{1F469}‍\u{1F467}‍\u{1F466}".repeat(12), // ZWJ family
    "é".repeat(50), // combining marks: 100 units, 100 points
    "\u{1F600}".repeat(40), // exactly 80 units / 40 points
  )],
  [1, fc.string({ unit: "grapheme", minLength: 1, maxLength: 90 })],
  [1, fc.string({ unit: "binary", minLength: 1, maxLength: 90 })],
);

/* ---------------------------------------------------------------- age ---
 * The change: zod 4 `.int()` means SAFE integer. Number.isInteger says yes for
 * 2**53 and 1e21, Number.isSafeInteger says no. */
const ageOdd = weighted(
  [4, pick(
    2 ** 53, 2 ** 53 + 2, 2 ** 54, 9007199254740993, 1e16, 1e21, 1e100,
    Number.MAX_SAFE_INTEGER, Number.MAX_SAFE_INTEGER + 1, Number.MAX_VALUE, -(2 ** 53),
  )],
  [2, fc.integer({ min: 13, max: 9999 }).map((n) => n * 2 ** 53)], // integral, past 2**53
  [2, pick(12, 13, 0, -1, 12.9999, 13.5, 1e-9, -0, Infinity, -Infinity, NaN)],
  [1, fc.double()],
  [1, pick(DROP, undefined, null, "42", true)],
);

/* ------------------------------------------------------------ website --- */
const urlOk = fc.stringMatching(/^https:\/\/[a-z0-9]{2,8}\.(com|org)(\/[a-z0-9]{1,6}){0,2}$/);
const urlOdd = weighted(
  [3, pick(
    "http://localhost", "http://localhost:3000/x", "https://example", "https://exämple.com",
    "https://xn--80ak6aa92e.com", "http://127.0.0.1:8080/x", "http://[::1]/",
    "ftp://files.example.com/x", "mailto:a@b.com", "javascript:alert(1)", "data:text/plain,hi",
    "https://x.com/a b", "https://x..com", "http://.com", "//example.com", "example.com",
    "https://user:pw@x.com", "https://x.com#frag", "https://x.com?q=1", "https://x.com\n",
    " https://x.com", "",
  )],
  [2, fc.webUrl()],
  [1, pick(DROP, undefined, 5, true)],
);

/* ------------------------------------------------------------------ ip ---
 * The change: zod 3 `.ip()` accepted an IPv6 zone index, zod 4 `z.ipv6()`
 * does not (src re-adds it with a refine -- that is what we are probing). */
const h4 = fc.stringMatching(/^[0-9a-f]{1,4}$/);
const plainIpv6 = weighted(
  [3, fc.array(h4, { minLength: 8, maxLength: 8 }).map((g) => g.join(":"))],
  [2, pick("::1", "::", "fe80::1", "2001:db8::1", "2001:db8:0:0:0:0:2:1", "0:0:0:0:0:0:0:1")],
