  [3, fc.dictionary(flagKey, weighted([3, fc.boolean()], [2, pick(0, 1, "true", "false", null, {}, [])]), { maxKeys: 3 })],
  [1, fc.dictionary(flagKey, fc.constant(undefined), { minKe

