// the zod 4 build BOTH accept an input while returning DIFFERENT parsed values.
// fuzz/run.js crashes on that case (it reads B.fields, which is undefined when
// both answers are ok), so the final generators must know exactly where it is.
//
// Here: every signup field is pinned to a value both versions accept, and ONLY
// `website` varies. Config is a constant valid object so only the signup
// differential can be the one that throws.
const fc = require("fast-check");

const DROP = Symbol("drop");

// A signup zod 3 accepts: RFC-shaped uuid, plain email, short ascii name,
// safe integer age, ipv4, real plan, boolean flags, explicit prefs.
const BASE = {
  id: "6ba7b810-9dad-11d1-80b4-00c04fd430c8",
  email: "user@example.com",
  name: "ada",
  age: 30,
  ip: "10.0.0.9",
  plan: "free",
  flags: { beta: true },
  prefs: { theme: "dark", retries: "3" },
};

const mutate = (field, arb) =>
  arb.map((v) => {
    const o = { ...BASE, prefs: { ...BASE.prefs }, flags: { ...BASE.flags } };
    if (v === DROP) delete o[field];
    else o[field] = v;
    return o;
  });

const pick = (...vs) => fc.constantFrom(...vs);
const weighted = (...pairs) => fc.oneof(...pairs.map(([weight, arbitrary]) => ({ weight, arbitrary })));

