// the shapes where zod 3's bare `new URL()` was more permissive than z.url().
const urlPool = weighted(
  [4, fc.webUrl()],
  [4, fc.stringMatching(/^https:\/\/[a-z0-9]{2,8}\.(com|org)(\/[a-z0-9]{1,6}){0,2}$/)],
  [4, pick(
    "https://x.com",
    "https://x.com/",
    "https://x.com/a",
    "HTTPS://X.COM",
    "https://X.CoM/Path",
    "https://x.com:443/",
    "https://x.com:8443/a",
    "https://x.com/a//b",
    "https://x.com/./a",
    "https://x.com/a/../b",
    "https://x.com?q=1",
    "https://x.com#frag",
    "https://x.com/a?q=1#f",
    "https://user:pw@x.com/",
    "https://exämple.com",
    "https://xn--80ak6aa92e.com",
    "http://localhost",
    "http://localhost:3000/x",
    "http://127.0.0.1:8080/x",
    "http://[::1]/",
  )],
  [2, pick(
    "ftp://files.example.com/x",
    "mailto:a@b.com",
    "javascript:alert(1)",
    "data:text/plain,hi",
    "tel:+15551234",
    "file:///etc/hosts",
    "//example.com",
    "example.com",
    "https://",
    "https://x.com ",
    " https://x.com",
    "https://x.com\n",
    "https://x..com",
    "http://.com",
    "",
  )],
  [1, pick(DROP, undefined)],
);

const signup = mutate("website", urlPool);
const config = fc.constant({ port: "8080", hosts: ["10.0.0.1"], timeoutMs: 5000 });

module.exports = { signup, config };

