// DIAGNOSTIC BUILD (temporary, step 15). Not the final generators.
//
// Why: fuzz/run.js line 38 reads `B.fields` whenever `A.ok` is true. When BOTH
// versions accept an input but the PARSED VALUE differs, B.fields is undefined
// and the whole run throws -- so the "accepted, but the PARSED VALUE changed"
// group can never print. run.js is harness-owned (read-only for me), so instead
// of guessing which field does it, this build probes the pairs directly: it is
// `require`d by run.js, so anything it logs at module load lands in the output
// BEFORE any sampling (and therefore before any crash).
//
// It still exports valid arbitraries at the end so the run continues.
const fc = require("fast-check");
const { answer, key } = require("../corpus/canon");
const oracle = require("../oracle/zod3");
const now = require("../dist/src");

const rep = (k, v) => (typeof v === "number" && !Number.isFinite(v) ? `__${v}__` : v);
const J = (v) => JSON.stringify(v, rep)?.replace(/"__(-?Infinity|NaN)__"/g, "$1");
const show = (r) => (r.ok ? `ok ${J(r.value)}` : `FAIL ${r.problems.join(" | ")}`);
const trunc = (s, n) => (s && s.length > n ? s.slice(0, n - 1) + "…" : s);

// A signup zod 3 accepts. NOTE: no `website` key -- `website` is added by probes.
const BASE = {
  id: "6ba7b810-9dad-11d1-80b4-00c04fd430c8",
  email: "user@example.com",
  name: "ada",
  age: 30,
  ip: "10.0.0.9",
  plan: "free",
  flags: { beta: true },
  prefs: { theme: "dark", retries: "3" },
};
const DROP = Symbol("drop");
const mut = (field, v) => {
  const o = { ...BASE, flags: { ...BASE.flags }, prefs: { ...BASE.prefs } };
  if (v === DROP) delete o[field];
  else o[field] = v;
  return o;
};

const signupProbes = [["BASE (no website key)", BASE]];
