/* ------------------------------------------------------------- sweep --- */
const SIGNUP_BASE = {
  id: "6ba7b810-9dad-11d1-80b4-00c04fd430c8",
  email: "user@example.com",
  name: "ada",
  age: 30,
  website: "https://example.com/a",
  ip: "10.0.0.9",
  plan: "free",
  flags: { beta: true },
  prefs: { theme: "dark", retries: "3" },
};
const CONFIG_BASE = { port: "8080", hosts: ["10.0.0.1"], timeoutMs: 5000 };

const make = (base, field, v) => {
  const o = { ...base };
  if (o.flags) o.flags = { ...o.flags };
  if (o.prefs) o.prefs = { ...o.prefs };
  if (o.hosts) o.hosts = [...o.hosts];
  if (v === DROP) delete o[field];
  else o[field] = v;
  return o;
};

const changedKeys = (a, b) => {
  const ks = new Set([...Object.keys(a || {}), ...Object.keys(b || {})]);
  return [...ks].filter((k) => J(a?.[k]) !== J(b?.[k]));
};

function sweep(title, base, pools, a, b) {
  const groups = new Map();
  let n = 0;
  for (const [field, pool] of pools) {
    for (const v of fc.sample(pool, { numRuns: 700, seed: 20261016 })) {
      n++;
      const x = make(base, field, v);
      const A = answer(a(x)), B = answer(b(x));
      if (key(A) === key(B)) continue;
      let g;
      if (A.ok && B.ok) g = `${field}: BOTH ACCEPT, VALUE CHANGED (${changedKeys(A.value, B.value).join(",") || "?"})`;
      else if (A.ok) g = `${field}: ACCEPTED -> REJECTED [${B.fields.join(",")}]`;
      else if (B.ok) g = `${field}: REJECTED [${A.fields.join(",")}] -> ACCEPTED`;
      else g = `${field}: both reject, fields differ: was [${A.fields.join(",")}] now [${B.fields.join(",")}]`;
      const e = groups.get(g) || { n: 0, ex: [] };
      e.n++;
      if (e.ex.length < 3) e.ex.push(`${field}=${trunc(J(v) ?? String(v))}`);
      groups.set(g, e);
    }
  }
  console.log(`\n=== SWEEP ${title}: ${n} one-field mutations, ${[...groups.values()].reduce((s, e) => s + e.n, 0)} different ===`);
  for (const [g, e] of [...groups.entries()].sort((p, q) => q[1].n - p[1].n)) {
    console.log(`  [${String(e.n).padStart(4)}] ${g}`);
    console.log(`         e.g. ${e.ex.join(" | ")}`);
  }
}

sweep("signup", SIGNUP_BASE, [
