    "data:text/plain,hi", "tel:+15551234", "file:///etc/hosts", "//example.com",
    "example.com", "https://", "https://x..com", "http://.com", "",
  )],
  [2, fc.stringMatching(/^[A-Za-z0-9:/?#@!$&'()*+,;=._~%-]{0,24}$/)], // garbage, but never whitespace
  [2, pick(DROP, undefined)],
  [1, pick(5, true, null)],
